%map = loadMapdt(2,1)
ldos_conductance_Together__Constants
clrs = ["r","b"] %[output:0f769d7e]
sytls = ["-",":"] %[output:68931112]
%%
close
V = map.vm*1000;
iphases = [1 2 1 2];
ibas = [1 1 2 2];

xyT.Row
%%
ps = [1 3 4] %[output:1302dfcd]
listCrs{1} = [1 2 3 4] %[output:4d9f5c24]
listCrs{2} = [1  3 ] %[output:00897c85]
listCrs{3} = [2  4 ] %[output:8a8e3a8d]
for ind = 1:3 %[output:group:012c5e53]
    p = ps(ind);
    subplot(2,2,p) %[output:0d5540ce]
    listCr = listCrs{ind};
    hold on
    for iCr = listCr
        cs = clrs(iphases(iCr)) + sytls(ibas(iCr));
        xrng = (0:r) + xyT{iCr,1}(1);
        yrng = (0:r) + xyT{iCr,1}(2);
        Gfcs = map.Gfinal0T(xrng,yrng,:);
        gfcs = squeeze(mean(mean(Gfcs)))*10;
        plot(V,gfcs,cs)
        xlim([-760 760]);
        ylim([0 1.1]);
        xlabel(labeler('E','meV'));
        ylabel(labeler('LDOS','a.u'));
        
        if ind == 1
        else
            xline(vFcss(ind-1,:));
        end
        legend(xyT.Row(listCr))
    end
    hold on
end %[output:group:012c5e53]
%%
f= gcf %[output:0f28483f] %[output:040a9e72]
f.Position = [10 10 1200 900]

